const inp = $('Called by workflow').first().json;
const action = String(inp.action || '');
let spec = {};
try { spec = JSON.parse(inp.arg2 || '{}'); } catch (e) { spec = {}; }
const out = { action, id: parseInt(inp.arg1, 10) || 0, error: '' };
if (action === 'watch_add') {
  const urls = String(spec.urls || '').split(/[\s,]+/).map(u => u.trim()).filter(Boolean)
    .map(u => /^https?:\/\//i.test(u) ? u : 'https://' + u);
  const channels = String(spec.channels || '__JC_CH_MAIN__').toLowerCase().split(/[\s,]+/).filter(Boolean);
  const bad = channels.filter(c => !["telegram", "email", "whatsapp", "call", "ai_call"].includes(c));
  const every = Math.round(Number(spec.every_hours || 3) * 60);
  if (!urls.length) out.error = 'no URL given';
  else if (urls.length > 5) out.error = 'at most 5 URLs per watch';
  else if (!String(spec.criteria || '').trim()) out.error = 'criteria is empty';
  else if (bad.length) out.error = 'unknown channel(s): ' + bad.join(', ') + '. allowed: ' + ["telegram", "email", "whatsapp", "call", "ai_call"].join(', ');
  else if (!(every >= 60)) out.error = 'every_hours must be at least 1';
  out.payload = Buffer.from(JSON.stringify({
    name: String(spec.name || urls[0]).slice(0, 80), urls, criteria: String(spec.criteria || '').slice(0, 1000),
    every_minutes: Math.min(every, 7 * 24 * 60), channels: [...new Set(channels)] }), 'utf8').toString('base64');
} else if (action === 'watch_remove') {
  if (!out.id) out.error = 'numeric watch id required (see list_watches)';
} else if (action !== 'watch_list') {
  out.error = 'unknown watch action';
}
return [{ json: out }];

const rows = $input.all().map(i => i.json).filter(r => r.id);
const action = $('Validate').first().json.action;
const fmt = r => `#${r.id} ${r.name} | every ${Math.round(r.every_minutes / 60 * 10) / 10}h via ${(r.channels || []).join(', ')}`
  + ` | ${(r.urls || []).join(' ')} | looking for: ${r.criteria}`
  + (r.last_run ? ` | last check ${r.last_run}` : ' | not checked yet') + (r.last_error ? ` | last error: ${r.last_error}` : '');
let result;
if (action === 'watch_add') result = rows.length ? 'saved watch ' + fmt(rows[0]) + '. The first check runs within 15 minutes; it only sends a short Telegram summary of what already matches, later checks alert on new matches via the chosen channels.' : 'ERROR: not saved';
else if (action === 'watch_remove') result = rows.length ? `removed watch #${rows[0].id} ${rows[0].name}` : 'ERROR: no watch with that id';
else result = rows.length ? rows.map(fmt).join('\n') : 'no active watches';
return [{ json: { result } }];
